export type SendInTail = Readonly<{ slideStart: number; messageStart: number | null }>;

/**
 * The send-in tail of one send-in, in frames after the send-in start (ROM RAM, `switchinanim`'s controller start = sweep k10):
 * `slideStart` = StartHealthboxSlideIn, `messageStart` = the next printstring's first glyph (null = not modelled: the player side's
 * cry-bound message). Species outside the table (none in the Factory) fall back to the frame-animation-free base.
 */
export function sendInTail(species: number, side: "player" | "opponent"): SendInTail {
  const castform = species === SEND_IN_TAIL_CASTFORM ? 1 : 0;
  if (side === "player") return Object.freeze({ slideStart: SEND_IN_TAIL_PLAYER_SLIDE + castform, messageStart: null });
  const row = SEND_IN_TAIL_SPECIES[species];
  const frames = row?.[0] ?? 0;
  const fn = row === undefined ? 0 : (SEND_IN_TAIL_FRONT_ANIM_DURATION[SEND_IN_TAIL_ANIM_IDS[row[1]]!] ?? 0) + (row[2] > 0 ? row[2] - 1 : 0);
  const slideStart = SEND_IN_TAIL_BASE + castform + Math.max(frames, fn);
  return Object.freeze({
    slideStart,
    messageStart: slideStart + (SEND_IN_TAIL_MESSAGE_EXCEPTIONS[species] ?? SEND_IN_TAIL_MESSAGE_AFTER_SLIDE),
  });
}
